using System.Reflection;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

string root=Directory.GetCurrentDirectory();while(!File.Exists(Path.Combine(root,"Assets/Script/Level/Tutorial/BuildTutorialDirector.cs")))root=Directory.GetParent(root)?.FullName??throw new InvalidOperationException("Project not found.");
ClassDeclarationSyntax Read(string file,string type)=>CSharpSyntaxTree.ParseText(File.ReadAllText(Path.Combine(root,file))).GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>().Single(node=>node.Identifier.ValueText==type);
var director=Read("Assets/Script/Level/Tutorial/BuildTutorialDirector.cs","BuildTutorialDirector");var manager=Read("Assets/Script/Level/Tutorial/TutorialManager.cs","TutorialManager");
string Method(ClassDeclarationSyntax type,string name)=>type.Members.OfType<MethodDeclarationSyntax>().Single(method=>method.Identifier.ValueText==name).ToFullString();
string Fields(ClassDeclarationSyntax type,string[] names)=>string.Join("\n",type.Members.OfType<FieldDeclarationSyntax>().Where(field=>field.Declaration.Variables.Any(variable=>names.Contains(variable.Identifier.ValueText))).Select(field=>field.ToFullString()));
string actual=Fields(director,new[]{"explicitPointerTarget","explicitPointerOffset","explicitPointerRotation","explicitPointerStepIndex","explicitPointerSequence","undoWarningRect","undoWarningText","undoWarningAuthoredPosition","undoWarningAuthoredSize","hasCachedUndoWarningLayout","hasUndoWarningLayoutSignature","undoWarningLastSafeArea","undoWarningLastParentBounds","undoWarningLastInstructionBounds","undoWarningLastScreenSize","undoWarningLastInstruction","undoWarningLastMessage","undoWarningReplacementManager"})+
    string.Join("\n",new[]{"PointArrow","TryRefreshTutorialPointer","ClearTutorialPointerOverride","IsPointerHierarchyUsable","ResolveUndoButtonRect","HideUndoPointer","PromptToolClick","PromptMaterialClick","PromptObservedTool","PromptOpenStatistics","PromptToggleGrid","LockAllUI","ClearTrackedToolButton","PromptUndoInvalidBar","RepointUndoArrowAfterLayout","NotifyUndoCompleted","ClearUndoPrompt","RefreshUndoWarningPresentation","ClearUndoWarningPresentation","LateUpdate","OnDisable","OnDestroy"}.Select(name=>Method(director,name)));
string managerActual=Fields(manager,new[]{"instructionVisualReplacementOwner","instructionVisualReplacementSequence","instructionVisualReplacementStepIndex","instructionVisualReplacementRect","instructionVisualReplacementGroup","instructionVisualReplacementAlpha","instructionVisualReplacementInteractable","instructionVisualReplacementBlocksRaycasts","instructionVisualReplacementWasAnimating","instructionVisualReplacementNextWasActive","instructionVisualReplacementSkipWasActive"})+
    manager.Members.OfType<PropertyDeclarationSyntax>().Single(property=>property.Identifier.ValueText=="IsTutorialPresentationSuppressed").ToFullString()+
    string.Join("\n",new[]{"Update","RestorePresentationAfterInspection","LateUpdate","GetInstructionVisualReplacementRect","SetInstructionVisualReplacement","RefreshInstructionVisualReplacement","ClearInstructionVisualReplacement"}.Select(name=>Method(manager,name)));
string boundary=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Boundary.cs.txt")).Replace("// ACTUAL_DIRECTOR",actual)
    .Replace("// ACTUAL_MANAGER_UPDATE",managerActual);
var references=((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")).Split(Path.PathSeparator).Select(path=>MetadataReference.CreateFromFile(path));
var compiled=CSharpCompilation.Create("BuildPointerOwnership_"+Guid.NewGuid().ToString("N"),new[]{CSharpSyntaxTree.ParseText(boundary),CSharpSyntaxTree.ParseText(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Scenarios.cs.txt")))},references,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
using MemoryStream output=new();var emitted=compiled.Emit(output);if(!emitted.Success)throw new InvalidOperationException(string.Join("\n",emitted.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error)));
int checks;try{checks=(int)Assembly.Load(output.ToArray()).GetType("Scenarios").GetMethod("Run").Invoke(null,null);}catch(TargetInvocationException error){throw new InvalidOperationException("Build pointer ownership failed.",error.InnerException);}
int guards=0;void Guard(bool okay,string label){guards++;if(!okay)throw new InvalidOperationException(label);}
foreach(string method in new[]{"BeginStep","LockAllUI","EndTutorial","AdvanceFromRequiredClick","NotifyCopySucceeded","HideUndoPointer"})Guard(Method(director,method).Contains("ClearTutorialPointerOverride();"),"Pointer override must reset in "+method);
Guard(!Method(director,"RepointUndoArrowAfterLayout").Contains("PointArrow("),"Undo coroutine may not bypass manager presentation guards.");
Guard(Method(director,"BeginSequence").Contains("EndTutorial();"),"New sequence must clear previous ownership.");
Guard(Method(manager,"Update").Contains("inspectionModalOwners.Count == 0 && presentationSuppressedFor == null"),"Shared refresh requires existing presentation guards.");
Guard(Method(director,"PointArrow").Contains("PointAtBuildTarget")&&!Method(director,"PointArrow").Contains("IsPointingAt"),"Same-target requests must always update offset/rotation.");
Guard(Method(manager,"RestorePresentationAfterInspection").Contains("TryRefreshTutorialPointer()")&&Method(manager,"RestorePresentationAfterInspection").Contains("PointAtBuildTarget"),"Immediate inspection restoration must use same build/Undo ownership and geometry.");
foreach(string method in new[]{"ClearUndoPrompt","OnDisable","OnDestroy"})Guard(Method(director,method).Contains("ClearUndoWarningPresentation();"),"Warning presentation must release on "+method);
Guard(Method(director,"RefreshUndoWarningPresentation").Contains("SetInstructionVisualReplacement(gameObject, true)")&&!Method(director,"RefreshUndoWarningPresentation").Contains("ShowNextStep("),"Required Undo always replaces instruction visuals without advancing.");
Guard(Method(manager,"ShowNextStep").Contains("IsAwaitingInvalidBarUndo) return;"),"Pending invalid Undo must block Continue progression.");
Guard(Method(manager,"SkipTutorial").Contains("IsAwaitingInvalidBarUndo) return;"),"Pending invalid Undo must block Skip progression without changing ordinary skip eligibility.");
foreach(string method in new[]{"ShowTutorialStep","PlayTutorial","CompleteTutorial","SuspendCurrentTutorial"})Guard(Method(manager,method).Contains("ClearInstructionVisualReplacement();"),"New or ended presentation must reset stale replacement: "+method);
Guard(!Method(manager,"SetInstructionVisualReplacement").Contains("SetActive(")&&!Method(manager,"ClearInstructionVisualReplacement").Contains(".gameObject.SetActive(")&&!Method(manager,"ClearInstructionVisualReplacement").Contains("panel.SetActive("),"Visual gate may not force-enable instruction or parent UI objects.");
Console.WriteLine($"PASS: {checks} executed actual build prompt/ownership/Manager.Update assertions + {guards} source guards. Pointer geometry/UGUI native rendering tested separately; no live scenes or player saves changed.");
